<?php
namespace App\Filament\Resources\Curriculums\RelationManagers;
use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Forms\Components\{Select,TextInput}; use Filament\Tables\{Actions\CreateAction,Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table};
class CoursesRelationManager extends RelationManager { protected static string $relationship='courses'; protected static ?string $title='Mata Kuliah Kurikulum'; public function form(Schema $schema):Schema{return $schema->components([Select::make('course_id')->label('Mata Kuliah')->relationship('course','name')->searchable()->preload()->required(),TextInput::make('semester')->label('Semester')->numeric()->minValue(1)->maxValue(14)->required(),Select::make('is_mandatory')->label('Sifat')->options([1=>'Wajib',0=>'Pilihan'])->default(1)->required(),TextInput::make('concentration')->label('Konsentrasi')]);} public function table(Table $table):Table{return $table->columns([TextColumn::make('course.code')->label('Kode'),TextColumn::make('course.name')->label('Mata Kuliah'),TextColumn::make('semester')->label('Semester'),TextColumn::make('is_mandatory')->label('Sifat')->formatStateUsing(fn($state)=>$state?'Wajib':'Pilihan')->badge()])->headerActions([CreateAction::make()->label('Tambah Mata Kuliah')])->actions([EditAction::make()->label('Ubah'),DeleteAction::make()->label('Hapus')->requiresConfirmation()]);}}
